<script lang="ts">
  import {onMount} from 'svelte';let {value=$bindable(),required=false,id}:{value?:any;required?:boolean;id:string}=$props();let hours:string[]=$state(['','','','','','','']);const days=['Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag'];
  onMount(()=>{try{const parsed=typeof value==='string'?JSON.parse(value):value;if(Array.isArray(parsed)&&parsed.length===7)hours=parsed.map(String);}catch{/* Unconfirmed pattern remains visibly empty. */}});
  function change(index:number,text:string){hours[index]=text;value=hours.every(v=>v!==''&&Number.isFinite(Number(v.replace(',','.'))))?JSON.stringify(hours.map(v=>Number(v.replace(',','.')))):'';}
</script>
<fieldset class="work-pattern" id={id}><legend>Bestätigte Arbeitswoche {required?'*':''}</legend><p>Vereinbarte Stunden je Tag. Für einen freien Tag tragen Sie bewusst 0 ein. Die Summe muss den Wochenstunden entsprechen.</p><div class="days">{#each days as day,index}<label for={`${id}-${index}`}>{day}<input id={`${id}-${index}`} inputmode="decimal" value={hours[index]} oninput={e=>change(index,e.currentTarget.value)} {required}/><span>Stunden</span></label>{/each}</div></fieldset>
<style>.work-pattern{border:0;padding:0;margin:0;min-width:0}.work-pattern legend{font-size:13px;font-weight:600}.work-pattern p{font-size:12px;margin:6px 0 15px;max-width:65ch}.days{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px}.days label{display:flex;flex-direction:column;gap:6px;font-size:11px;color:var(--muted)}.days input{width:100%;min-height:43px;padding:10px;border:1px solid var(--line);border-radius:7px;font-size:15px;color:var(--ink);background:white}.days span{font-size:10px}@media(max-width:760px){.days{grid-template-columns:repeat(2,minmax(0,1fr))}.days label{font-size:13px}.days input{font-size:16px;min-height:48px}.work-pattern p{font-size:13px}}</style>
